1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import java.util.HashSet;
8	import java.util.Set;
9	import java.util.stream.Collectors;
10	
11	import net.officefloor.plugin.variable.Val;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	import org.springframework.samples.petclinic.rest.function.common.Localities;
15	
16	/**
17	 * Assigns the {@code customerCode} to a newly built owner, formatted
18	 * {@code <REGION>-<HASH8>} where {@code REGION} is the region code derived from the
19	 * owner's postcode (see {@link Localities#locality(String, String)}) and {@code HASH8}
20	 * is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
21	 * normalized telephone (E.164, see {@link OwnerTelephone}) concatenated with its last
22	 * name (e.g. {@code NSW-1A2B3C4D}).
23	 *
24	 * <p>This is a stable identity: the region-and-hash value carries no sequence number, so
25	 * it does not depend on how many owners already exist. When that value collides with an
26	 * existing owner's {@code customerCode}, {@code -<n>} is appended with the smallest
27	 * {@code n} of 2 or more that makes it unique, so distinct owners always get distinct
28	 * customerCodes. Every value built from the customerCode — the
29	 * membershipNumber and its checkDigit, the create audit line and the derived locality —
30	 * follows from this region-and-hash identity. Mutates the owner in place (the same object
31	 * {@link SaveOwner} persists).
32	 */
33	public class AssignOwnerCustomerCode {
34	
35	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
36	        String region = Localities.locality(owner.getCity(), owner.getPostcode());
37	        String telephone = OwnerTelephone.canonical(owner.getTelephone());
38	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
39	        String base = region + "-" + hash8(telephone + lastName);
40	
41	        Set<String> taken = ownerRepository.findAll().stream()
42	                .filter(existing -> existing.getId() == null
43	                        || !existing.getId().equals(owner.getId()))
44	                .map(Owner::getCustomerCode)
45	                .filter(code -> code != null)
46	                .collect(Collectors.toCollection(HashSet::new));
47	
48	        String customerCode = base;
49	        for (int n = 2; taken.contains(customerCode); n++) {
50	            customerCode = base + "-" + n;
51	        }
52	        owner.setCustomerCode(customerCode);
53	    }
54	
55	    /** The first 8 upper-case hex characters of the SHA-256 digest of {@code input}. */
56	    private static String hash8(String input) {
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256")
59	                    .digest(input.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder(8);
61	            for (int i = 0; i < 4; i++) {
62	                sb.append(String.format("%02X", digest[i]));
63	            }
64	            return sb.toString();
65	        }
66	        catch (NoSuchAlgorithmException e) {
67	            throw new IllegalStateException(e);
68	        }
69	    }
70	}
