8	/**
9	 * Shared derivation of an owner's household identity. The {@code householdId} is now
10	 * <em>deterministic</em>: the first 12 hex characters of SHA-256 over
11	 * {@code normalizedLastName + "|" + postcode}. Owners with the same last name (compared
12	 * case-insensitively with collapsed whitespace) and the same postcode therefore resolve to
13	 * the same householdId automatically, without any creation-order back-fill.
14	 *
15	 * <p>Used by {@link AssignOwnerHousehold} (which stamps the id onto a new owner), by
16	 * {@link EnsureUniqueOwnerIdentity} (which blocks a second owner of an existing household) and
17	 * by {@link AssignOwnerPossibleDuplicate} (which treats fellow household members as declared,
18	 * not suspected, duplicates), so all three agree on exactly what a household is.
19	 */
20	final class OwnerHousehold {
21	
22	    private OwnerHousehold() {
23	    }
24	
25	    /**
26	     * The deterministic {@code householdId} for the given last name and postcode, or
27	     * {@code null} when no postcode is supplied (an owner with no postcode has no household).
28	     */
29	    static String idFor(String lastName, String postcode) {
30	        if (postcode == null || postcode.isBlank()) {
31	            return null;
32	        }
33	        return id(normalizeName(lastName), postcode.trim());
34	    }
35	
36	    /** Stable 12-char upper-hex identifier derived from the deterministic household key. */
37	    static String id(String normalizedLastName, String postcode) {
38	        String key = normalizedLastName + "|" + postcode;
39	        try {
40	            byte[] digest = MessageDigest.getInstance("SHA-256")
41	                    .digest(key.getBytes(StandardCharsets.UTF_8));
